// ── Tolerances ──────────────────────────────────────────────────────────────

const TIGHT_TOL: f64 = 0.01;
const MEDIUM_TOL: f64 = 0.1;
const LOOSE_TOL: f64 = 1.0;
const VERY_LOOSE_TOL: f64 = 5.0;
const VSA_TOL: f64 = 0.5;
const CHI_TOL: f64 = 0.05;

// ── Types ───────────────────────────────────────────────────────────────────

struct ScalarCheck {
    name: &'static str,
    csv_column: &'static str,
    descriptor: Box<dyn Descriptor>,
    extract: ExtractKind,
    tolerance: f64,
}

enum ExtractKind {
    Float,
    Int,
}

#[derive(Clone)]
struct CompResult {
    molecule: String,
    descriptor: String,
    ferrum: f64,
    rdkit: f64,
    diff: f64,
    tol: f64,
    passed: bool,
}

// ── CSV Loader ──────────────────────────────────────────────────────────────

const DEFAULT_MAX_REFERENCE_ROWS: usize = 500;

/// Implements row limit.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn reference_row_limit() -> usize {
    env::var("FERRUM_RDKIT_REFERENCE_ROWS")
        .ok()
        .and_then(|s| s.parse::<usize>().ok())
        .filter(|&n| n > 0)
        .unwrap_or(DEFAULT_MAX_REFERENCE_ROWS)
}

/// Loads reference.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn load_reference() -> Vec<(String, String, HashMap<String, String>)> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/rdkit_reference_coconut.csv");
    let mut rdr = csv::Reader::from_path(&path)
        .unwrap_or_else(|e| panic!("Cannot open {}: {e}", path.display()));
    let headers: Vec<String> = rdr
        .headers()
        .unwrap()
        .iter()
        .map(|s| s.to_string())
        .collect();
    let mut out = Vec::new();
    let max_reference_rows = reference_row_limit();
    for rec in rdr.records() {
        let rec = rec.expect("valid CSV row");
        let smiles = rec[0].to_string();
        let name = rec[1].to_string();
        let mut vals = HashMap::new();
        for (i, h) in headers.iter().enumerate().skip(2) {
            vals.insert(h.clone(), rec[i].to_string());
        }
        out.push((smiles, name, vals));
        if out.len() >= max_reference_rows {
            break;
        }
    }
    out
}

/// Parses csv f64.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn parse_csv_f64(s: &str) -> Option<f64> {
    if s == "NaN" || s.is_empty() {
        None
    } else {
        s.parse().ok()
    }
}

