// ── Reporting Helpers ───────────────────────────────────────────────────────

/// Implements separator.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn print_separator(title: &str) {
    let sep = "=".repeat(90);
    eprintln!("\n{sep}");
    eprintln!("  {title}");
    eprintln!("{sep}");
}

/// Implements summary.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn print_summary(results: &[CompResult], section: &str) {
    let total = results.len();
    let passed = results.iter().filter(|r| r.passed).count();
    let failed = total - passed;

    print_separator(section);
    eprintln!(
        "  Total: {total} | Passed: {passed} | Failed: {failed} | Rate: {:.1}%",
        if total > 0 {
            passed as f64 / total as f64 * 100.0
        } else {
            0.0
        }
    );

    if failed > 0 {
        // Group failures by descriptor
        let mut by_desc: HashMap<String, Vec<&CompResult>> = HashMap::new();
        for r in results.iter().filter(|r| !r.passed) {
            by_desc.entry(r.descriptor.clone()).or_default().push(r);
        }
        let mut descs: Vec<_> = by_desc.keys().cloned().collect();
        descs.sort();

        eprintln!("\n  FAILURES:");
        eprintln!(
            "  {:<22} {:<30} {:>10} {:>10} {:>10} {:>6}",
            "Descriptor", "Molecule", "Ferrum", "RDKit", "Diff", "Tol"
        );
        eprintln!("  {}", "-".repeat(88));
        for desc in &descs {
            for r in &by_desc[desc] {
                let mol_short = if r.molecule.len() > 28 {
                    format!("{}...", &r.molecule[..25])
                } else {
                    r.molecule.clone()
                };
                eprintln!(
                    "  {:<22} {:<30} {:>10.4} {:>10.4} {:>10.4} {:>6.2}",
                    r.descriptor, mol_short, r.ferrum, r.rdkit, r.diff, r.tol
                );
            }
        }
    }

    // Also print per-descriptor pass rates
    let mut desc_stats: HashMap<String, (usize, usize)> = HashMap::new();
    for r in results {
        let entry = desc_stats.entry(r.descriptor.clone()).or_insert((0, 0));
        entry.0 += 1;
        if r.passed {
            entry.1 += 1;
        }
    }
    let mut desc_list: Vec<_> = desc_stats.into_iter().collect();
    desc_list.sort_by(|a, b| a.0.cmp(&b.0));

    eprintln!("\n  PER-DESCRIPTOR SUMMARY:");
    eprintln!(
        "  {:<22} {:>6} {:>6} {:>8}",
        "Descriptor", "Total", "Pass", "Rate"
    );
    eprintln!("  {}", "-".repeat(46));
    for (name, (total, pass)) in &desc_list {
        let rate = if *total > 0 {
            *pass as f64 / *total as f64 * 100.0
        } else {
            0.0
        };
        let marker = if rate == 100.0 {
            "✓"
        } else if rate >= 80.0 {
            "~"
        } else {
            "✗"
        };
        eprintln!(
            "  {marker} {:<20} {:>6} {:>6} {:>7.1}%",
            name, total, pass, rate
        );
    }
}

// ── Test: Scalar Descriptors ────────────────────────────────────────────────

#[test]
/// Runs regression test for rdkit scalar descriptors.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn rdkit_scalar_descriptors() {
    let reference = load_reference();
    let checks = scalar_checks();
    let mut results: Vec<CompResult> = Vec::new();
    let mut parse_failures = Vec::new();

    for (smiles, name, values) in &reference {
        let mut mol = match parse_smiles(smiles) {
            Ok(m) => m,
            Err(e) => {
                parse_failures.push(format!("{name} ({smiles}): {e}"));
                continue;
            }
        };

        for check in &checks {
            let csv_val = match values.get(check.csv_column) {
                Some(v) => v,
                None => continue,
            };
            let rdkit_val = match parse_csv_f64(csv_val) {
                Some(v) => v,
                None => continue,
            };

            let ferrum_val = match check.extract {
                ExtractKind::Float => match check.descriptor.calculate(&mut mol, &mut ferrum_core::desc::context::CalculationContext::new()) {
                    DescriptorValue::Float(v) => v as f64,
                    DescriptorValue::Float64(v) => v,
                    _ => continue,
                },
                ExtractKind::Int => match check.descriptor.calculate(&mut mol, &mut ferrum_core::desc::context::CalculationContext::new()) {
                    DescriptorValue::Int(v) => v as f64,
                    _ => continue,
                },
            };

            let diff = (ferrum_val - rdkit_val).abs();
            let tol = if check.tolerance == 0.0 {
                0.5
            } else {
                check.tolerance
            };
            results.push(CompResult {
                molecule: format!("{name}"),
                descriptor: check.name.to_string(),
                ferrum: ferrum_val,
                rdkit: rdkit_val,
                diff,
                tol,
                passed: diff <= tol,
            });
        }
    }

    if !parse_failures.is_empty() {
        eprintln!("\n  PARSE FAILURES ({}):", parse_failures.len());
        for f in &parse_failures {
            eprintln!("    {f}");
        }
    }

    print_summary(&results, "SCALAR DESCRIPTORS vs RDKit");
}

// ── Test: VSA Descriptors ───────────────────────────────────────────────────

/// Implements vec.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn compare_vec(
    desc: &dyn Descriptor,
    smiles: &str,
    name: &str,
    desc_name: &str,
    columns: &[String],
    values: &HashMap<String, String>,
    tol: f64,
) -> Vec<CompResult> {
    let mut out = Vec::new();
    let mut mol = match parse_smiles(smiles) {
        Ok(m) => m,
        Err(_) => return out,
    };

    let value = desc.calculate(&mut mol, &mut ferrum_core::desc::context::CalculationContext::new());
    let ferrum_vec: Vec<f64> = match &value {
        DescriptorValue::FloatVec(v) => v.iter().map(|&x| x as f64).collect(),
        DescriptorValue::IntU16Vec(v) => v.iter().map(|&x| x as f64).collect(),
        _ => return out,
    };

    for (i, col) in columns.iter().enumerate() {
        if let Some(csv_val) = values.get(col) {
            if let Some(rdkit_val) = parse_csv_f64(csv_val) {
                let ferrum_val = if i < ferrum_vec.len() {
                    ferrum_vec[i]
                } else {
                    0.0
                };
                let diff = (ferrum_val - rdkit_val).abs();
                out.push(CompResult {
                    molecule: name.to_string(),
                    descriptor: format!("{desc_name}[{i}]"),
                    ferrum: ferrum_val,
                    rdkit: rdkit_val,
                    diff,
                    tol,
                    passed: diff <= tol,
                });
            }
        }
    }
    out
}

#[test]
/// Runs regression test for rdkit vsa descriptors.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn rdkit_vsa_descriptors() {
    let reference = load_reference();
    let slogp_cols: Vec<String> = (1..=12).map(|i| format!("SlogP_VSA{i}")).collect();
    let smr_cols: Vec<String> = (1..=10).map(|i| format!("SMR_VSA{i}")).collect();
    let peoe_cols: Vec<String> = (1..=14).map(|i| format!("PEOE_VSA{i}")).collect();

    let mut results = Vec::new();

    for (smiles, name, values) in &reference {
        results.extend(compare_vec(
            &SlogpVSA,
            smiles,
            name,
            "SlogpVSA",
            &slogp_cols,
            values,
            VSA_TOL,
        ));
        results.extend(compare_vec(
            &SmrVSA, smiles, name, "SmrVSA", &smr_cols, values, VSA_TOL,
        ));
        results.extend(compare_vec(
            &PeoeVsa, smiles, name, "PeoeVsa", &peoe_cols, values, VSA_TOL,
        ));
    }

    print_summary(&results, "VSA DESCRIPTORS vs RDKit");
}

// ── Test: Chi & Kappa Indices ───────────────────────────────────────────────

#[test]
/// Runs regression test for rdkit chi kappa indices.
///
/// Function context: `crates/ferrum_core/tests/rdkit_comparison.rs`.
/// Test-layer note: this assertion path pins expected behavior to prevent regressions.
fn rdkit_chi_kappa_indices() {
    let reference = load_reference();

    // Map RDKit CSV columns to ferrum ChiIndices vector positions
    // Ferrum: [0-7] ChiPath, [8-15] ChiValencePath, [16-17] Cluster, [18-22] Chain, [23-25] PathCluster
    let chi_map: Vec<(&str, usize)> = vec![
        ("Chi0", 0),
        ("Chi0v", 8),
        ("Chi1", 1),
        ("Chi1v", 9),
        ("Chi2v", 10),
        ("Chi3v", 11),
        ("Chi4v", 12),
    ];
    let kappa_map: Vec<(&str, usize)> = vec![("Kappa1", 0), ("Kappa2", 1), ("Kappa3", 2)];

    let mut results = Vec::new();

    for (smiles, name, values) in &reference {
        let mut mol = match parse_smiles(smiles) {
            Ok(m) => m,
            Err(_) => continue,
        };

        if let DescriptorValue::FloatVec(ref chi_vec) = ChiIndices.calculate(&mut mol, &mut ferrum_core::desc::context::CalculationContext::new()) {
            for (col, idx) in &chi_map {
                if let Some(rdkit_val) = values.get(*col).and_then(|v| parse_csv_f64(v)) {
                    let fv = chi_vec[*idx] as f64;
                    let diff = (fv - rdkit_val).abs();
                    results.push(CompResult {
                        molecule: name.clone(),
                        descriptor: format!("Chi:{col}"),
                        ferrum: fv,
                        rdkit: rdkit_val,
                        diff,
                        tol: CHI_TOL,
                        passed: diff <= CHI_TOL,
                    });
                }
            }
        }

        if let DescriptorValue::FloatVec(ref kv) = KappaIndices.calculate(&mut mol, &mut ferrum_core::desc::context::CalculationContext::new()) {
            for (col, idx) in &kappa_map {
                if let Some(rdkit_val) = values.get(*col).and_then(|v| parse_csv_f64(v)) {
                    let fv = kv[*idx] as f64;
                    let diff = (fv - rdkit_val).abs();
                    results.push(CompResult {
                        molecule: name.clone(),
                        descriptor: format!("Kappa:{col}"),
                        ferrum: fv,
                        rdkit: rdkit_val,
                        diff,
                        tol: CHI_TOL,
                        passed: diff <= CHI_TOL,
                    });
                }
            }
        }
    }

    print_summary(&results, "CHI / KAPPA INDICES vs RDKit");
}

